        return node

    def node_demand(node):
        if isinstance(node, dict):
            for k in ("demand", "quantity", "d"):
                if k in node:
                    return node[k]
        return 0

    def node_xy(node):
        if isinstance(node, dict):
            if "x" in node and "y" in node:
                return node["x"], node["y"]
            if "coord" in node and isinstance(node["coord"], (list, tuple)) and len(node["coord"]) >= 2:
                return node["coord"][0], node["coord"][1]
        return None

    depot = None
    if "depot" in instance:
        depot = instance["depot"]
    elif "nodes" in instance and isinstance(instance["nodes"], list) and instance["nodes"]:
        depot = instance["nodes"][0]
    elif "customers" in instance and isinstance(instance["customers"], list):
        depot = {"id": 0, "x": 0, "y": 0, "demand": 0}
    else:
        depot = {"id": 0, "x": 0, "y": 0, "demand": 0}

    dep_id = node_id(depot)
    dep_xy = node_xy(depot)

    customers = []
    if "customers" in instance and isinstance(instance["customers"], list):
        customers = instance["customers"]
    elif "nodes" in instance and isinstance(instance["nodes"], list):
        customers = [n for n in instance["nodes"] if node_id(n) != dep_id]
    elif "demands" in instance:
        demands = instance["demands"]
        coords = instance.get("coords", None)
        for i in range(1, len(demands)):
            n = {"id": i, "demand": demands[i]}
            if isinstance(coords, list) and i < len(coords) and isinstance(coords[i], (list, tuple)) and len(coords[i]) >= 2:
                n["x"], n["y"] = coords[i][0], coords[i][1]
            customers.append(n)

    cap = get_capacity(instance)

    demand = {}
    coord = {}
    cust = []
    for n in customers:
        cid = node_id(n)
        if cid == dep_id:
            continue
        cust.append(cid)
        demand[cid] = node_demand(n)
        coord[cid] = node_xy(n)

    if not cust:
        return []

    have_coords = dep_xy is not None
    if have_coords:
        for c in cust:
            if coord.get(c) is None:
                have_coords = False
                break

    dist_cache = {}

    if have_coords:
        def dist(a, b):
            key = (a, b)
            if key in dist_cache:
                return dist_cache[key]
            if a == dep_id:
                ax, ay = dep_xy
            else:
                ax, ay = coord[a]
            if b == dep_id:
                bx, by = dep_xy
            else:
                bx, by = coord[b]
            dx = ax - bx
            dy = ay - by
            d = (dx * dx + dy * dy) ** 0.5
            dist_cache[key] = d
            dist_cache[(b, a)] = d
            return d
    else:
        def dist(a, b):
            ai = 0 if a == dep_id else int(a)
            bi = 0 if b == dep_id else int(b)
            return abs(ai - bi) + 1e-6 * (ai + bi)

    order = list(cust)
    order.sort(key=lambda c: (-demand.get(c, 0), dist(dep_id, c), c))

    unserved = {}
    for c in cust:
        unserved[c] = True

    routes = []

    def route_load(rt):
        s = 0
        for x in rt:
            s += demand.get(x, 0)
        return s

    def route_cost(rt):
        if not rt:
            return 0
        c = dist(dep_id, rt[0])
        for i in range(len(rt) - 1):
            c += dist(rt[i], rt[i + 1])
        c += dist(rt[-1], dep_id)
        return c

    # Constructive: seed by far/high-demand, then cheapest feasible insertion with regret
    while unserved:
        seed = None
        best_seed_key = None
        for c in order:
            if c in unserved and demand.get(c, 0) <= cap:
                k = (dist(dep_id, c), -demand.get(c, 0), c)
                if best_seed_key is None or k < best_seed_key:
                    best_seed_key = k
                    seed = c
        if seed is None:
            # Infeasible singletons fallback
            for c in order:
                if c in unserved:
                    routes.append([c])
                    del unserved[c]
            break

        rt = [seed]
        load = demand.get(seed, 0)
        del unserved[seed]

        while True:
            candidates = []
            for c in order:
                if c not in unserved:
                    continue
                d = demand.get(c, 0)
                if load + d > cap:
                    continue
                best_pos = None
                best_delta = None
                prev = dep_id
                for i in range(len(rt) + 1):
                    nxt = dep_id if i == len(rt) else rt[i]
                    delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                    if best_delta is None or delta < best_delta or (delta == best_delta and i < best_pos):
                        best_delta = delta
                        best_pos = i
                    prev = nxt
                # regret-2 signal
                second = None
                second_delta = None
                prev = dep_id
                for i in range(len(rt) + 1):
                    nxt = dep_id if i == len(rt) else rt[i]
                    delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                    if second_delta is None or delta < second_delta:
                        second_delta = delta
                    prev = nxt
                regret = (second_delta - best_delta) if second_delta is not None else 0
                candidates.append((best_delta, -regret, dist(dep_id, c), -d, c, best_pos))
            if not candidates:
                break
            candidates.sort()
            _, _, _, _, c, pos = candidates[0]
            rt.insert(pos, c)
            load += demand.get(c, 0)
            del unserved[c]

        routes.append(rt)

    # Repair / improve: relocate and 2-opt within routes, then cross-route relocate
    improved = True
    iters = 0
    while improved and iters < 30:
        iters += 1
        improved = False

        # 2-opt within each route
        for r in range(len(routes)):
            rt = routes[r]
            n = len(rt)
            if n < 4:
                continue
            best_gain = 0
            best_i = best_j = None
            base = route_cost(rt)
            for i in range(n - 1):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = rt[:i + 1] + rt[i + 1:j + 1][::-1] + rt[j + 1:]
                    gain = base - route_cost(cand)
                    if gain > best_gain + 1e-12 or (gain == best_gain and (best_i is None or (i, j) < (best_i, best_j))):
                        best_gain = gain
                        best_i, best_j = i, j
            if best_gain > 1e-12:
                rt[:] = rt[:best_i + 1] + rt[best_i + 1:best_j + 1][::-1] + rt[best_j + 1:]
                improved = True

        # relocate between routes
        best_move = None
        best_delta = 0
        for a in range(len(routes)):
            ra = routes[a]
            for i, c in enumerate(ra):
                da = demand.get(c, 0)
                for b in range(len(routes)):
                    if a == b:
                        continue
                    rb = routes[b]
                    if route_load(rb) + da > cap:
                        continue
                    # remove from a
                    ra_prev = dep_id if i == 0 else ra[i - 1]
                    ra_next = dep_id if i == len(ra) - 1 else ra[i + 1]
                    remove_delta = dist(ra_prev, ra_next) - dist(ra_prev, c) - dist(c, ra_next)
                    # best insert into b
                    best_ins = None
                    best_ins_delta = None
                    for pos in range(len(rb) + 1):
                        pb = dep_id if pos == 0 else rb[pos - 1]
                        nb = dep_id if pos == len(rb) else rb[pos]
                        ins_delta = dist(pb, c) + dist(c, nb) - dist(pb, nb)
                        if best_ins_delta is None or ins_delta < best_ins_delta or (ins_delta == best_ins_delta and pos < best_ins):
                            best_ins_delta = ins_delta
                            best_ins = pos
                    delta = remove_delta + best_ins_delta
                    if delta < best_delta - 1e-12 or (delta == best_delta and best_move is not None and (a, i, b, best_ins) < best_move[:4]):
                        best_delta = delta
                        best_move = (a, i, b, best_ins, c)
        if best_move is not None and best_delta < -1e-12:
            a, i, b, pos, c = best_move
            if a < b:
                ra = routes[a]
                rb = routes[b]
            else:
                rb = routes[b]
                ra = routes[a]
            # remove
            del routes[a][i]
            if a == b:
                continue
            routes[b].insert(pos, c)
            improved = True

    # clean empty routes and ensure deterministic order
    routes = [rt for rt in routes if rt]
    routes.sort(key=lambda rt: (route_cost(rt), len(rt), rt[0], rt))

    return routes
